arguments.command:
cd /app && grep -nE "import|socket|open\(|subprocess|os\.|system" submission/main.py | head -20; echo "---- verify no file writes / network:"; python3 - << 'EOF'
import ast
tree = ast.parse(open('/app/submission/main.py').read())
imports = set()
for node in ast.walk(tree):
    if isinstance(node, ast.Import):
        for a in node.names: imports.add(a.name)
    elif isinstance(node, ast.ImportFrom):
        imports.add(node.module)
print("imports:", sorted(imports))
# check for any calls that touch the filesystem or network
bad = []
for node in ast.walk(tree):
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
        if node.func.id in ('open', 'eval', 'exec', 'compile', '__import__'):
            bad.append(node.func.id)
print("risky calls:", bad)
EOF
